// Keep the parts worth reading on a phone: the Overnight note, the Numbers,
// anything archived, the Judger queue and the book. Discord caps a message at 2000.
const md = $input.first().json.data || $input.first().json.body || '';
const want = ['Overnight', 'Numbers', 'Scenes archived since the last run', 'Judger queue', 'The book'];
const out = [];
let keep = false;
for (const line of String(md).split('\n')) {
  if (line.startsWith('# ')) { out.push('**' + line.slice(2).trim() + '**'); continue; }
  if (line.startsWith('## ')) { keep = want.some(w => line.slice(3).startsWith(w)); if (keep) out.push('__' + line.slice(3).trim() + '__'); continue; }
  if (keep) out.push(line);
}
let text = out.join('\n').replace(/\n{3,}/g, '\n\n').trim();
if (text.length > 1900) text = text.slice(0, 1900) + '\n...(reports/nightly.md has the rest)';
const status = $('How did it go').item.json;
if (status.state !== 'done') text = '(the nightly ended ' + status.state + ', exit ' + status.exit_code + ')\n\n' + text;
return [{ json: { content: text, state: status.state } }];
